package com.lunghealth.monitoring.model.entity;

import com.lunghealth.monitoring.model.enums.AlertType;
import com.lunghealth.monitoring.model.enums.RiskLevel;
import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Clinical entity representing an urgent automated pulmonary health alert.
 *
 * <p>Generated by the clinical risk engine when critical physiological thresholds (such as
 * severe hypoxemia SpO2 &lt; 85%, marked tachypnea RR &gt; 28 bpm, or red-flag hemoptysis)
 * are breached. Tracks provider acknowledgment status and timestamp for medical auditing.</p>
 *
 * @author Dr. Eleanor Vance, MD, FCCP / PulmoCare Clinical Informatics
 */
@Entity
@Table(name = "health_alerts")
public class HealthAlert {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Patient associated with this clinical safety alert. */
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "patient_id", nullable = false)
    private Patient patient;

    /** Exact timestamp when the alert condition was triggered. */
    @Column(nullable = false)
    private LocalDateTime timestamp;

    /** Risk severity of this alert condition (HIGH, CRITICAL). */
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    private RiskLevel severity;

    /** Categorized clinical alert condition type. */
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 50)
    private AlertType alertType;

    /** Clinically explicit directive and diagnostic rationale explaining the alert trigger. */
    @Column(nullable = false, length = 500)
    private String message;

    /** Whether an attending physician, triage nurse, or respiratory therapist has acknowledged this alert. */
    @Column(nullable = false)
    private Boolean acknowledged = false;

    /** Timestamp when acknowledgment was registered by the healthcare team. */
    private LocalDateTime acknowledgedAt;

    public HealthAlert() {}

    public HealthAlert(Patient patient, RiskLevel severity, AlertType alertType, String message) {
        this.patient = patient;
        this.severity = severity;
        this.alertType = alertType;
        this.message = message;
        this.timestamp = LocalDateTime.now();
        this.acknowledged = false;
    }

    @PrePersist
    protected void onCreate() {
        if (this.timestamp == null) {
            this.timestamp = LocalDateTime.now();
        }
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public Patient getPatient() { return patient; }
    public void setPatient(Patient patient) { this.patient = patient; }

    public LocalDateTime getTimestamp() { return timestamp; }
    public void setTimestamp(LocalDateTime timestamp) { this.timestamp = timestamp; }

    public RiskLevel getSeverity() { return severity; }
    public void setSeverity(RiskLevel severity) { this.severity = severity; }

    public AlertType getAlertType() { return alertType; }
    public void setAlertType(AlertType alertType) { this.alertType = alertType; }

    public String getMessage() { return message; }
    public void setMessage(String message) { this.message = message; }

    public Boolean getAcknowledged() { return acknowledged; }
    public void setAcknowledged(Boolean acknowledged) { this.acknowledged = acknowledged; }

    public LocalDateTime getAcknowledgedAt() { return acknowledgedAt; }
    public void setAcknowledgedAt(LocalDateTime acknowledgedAt) { this.acknowledgedAt = acknowledgedAt; }
}
